static int cam_example_place_direction(const ipacket_t *packet, mmt_proto_index_t proto_index, int64_t *offset, int64_t *length)
{
    int ok = 1;

    (void) packet;
    (void) proto_index;
    *offset = 22;
    *length = 2;
    return ok;
}

/* The value of direction: 0 when it is absent from this packet. */
static int cam_example_get_direction(const ipacket_t *packet, mmt_proto_index_t proto_index, uint64_t *value)
{
    int64_t offset, length;
    const uint8_t *p;

    if (!cam_example_place_direction(packet, proto_index, &offset, &length)) {
        return 0;
    }
    p = cam_example_bytes(packet, proto_index, offset, length);
    if (p == NULL) {
        return 0;
    }
    *value = cam_example_read(p, 2);
    return 1;
}

/* Extracts direction into the attribute's data. */
static int cam_example_direction_extraction(const ipacket_t *packet, mmt_proto_index_t proto_index, attribute_t *extracted_data)
{
    uint64_t value;

    if (!cam_example_get_direction(packet, proto_index, &value)) {
        return 0;
    }
    *(uint16_t *) extracted_data->data = (uint16_t) value;
    return 1;
}

/*
 * Classifies CAM_EXAMPLE after its parent udp (plugin.yaml): when
 * every match holds on the parent's bytes, CAM_EXAMPLE starts 8 bytes
 * after the start of the parent, at previous_index + 1.
 */
static mmt_classify_verdict_t cam_example_classify_after_udp(ipacket_t *ipacket, unsigned previous_index)
{
    classified_proto_t next;
    int64_t caplen = (int64_t) ipacket->p_hdr->caplen;
    int64_t start = (int64_t) get_packet_offset_at_index(ipacket, previous_index);
    const uint8_t *p;

    if (start < 0 || start > caplen - 10) {
        return MMT_CLASSIFY_SKIP;
    }
    p = &ipacket->data[start];
    if ((((uint64_t) p[8] << 8) | (uint64_t) p[9]) != 0x202u) {
        return MMT_CLASSIFY_SKIP;
    }
    memset(&next, 0, sizeof(next));
    next.proto_id = PROTO_CAM_EXAMPLE;
    next.offset = 8;
    next.status = Classified;
    if (!set_classified_proto(ipacket, previous_index + 1, next)) {
        return MMT_CLASSIFY_SKIP;
    }
    return MMT_CLASSIFY_MATCHED;
}

