int init_cam_example_proto_struct(void)
{
    protocol_t *protocol_struct;
    size_t i;

    /* mmt-dpi ignores a protocol name that is already registered (names
     * compare case-insensitively): refuse to load instead. */
    if (get_protocol_id_by_name(PROTO_CAM_EXAMPLE_ALIAS) != 0) {
        mmt_log_error("init_cam_example_proto_struct: protocol name %s is already registered", PROTO_CAM_EXAMPLE_ALIAS);
        return 0;
    }
    protocol_struct = init_protocol_struct_for_registration(PROTO_CAM_EXAMPLE, PROTO_CAM_EXAMPLE_ALIAS);
    if (protocol_struct == NULL) {
        mmt_log_error("init_cam_example_proto_struct: protocol id %d is out of range or already registered", PROTO_CAM_EXAMPLE);
        return 0;
    }
    for (i = 0; i < sizeof(cam_example_attributes_metadata) / sizeof(cam_example_attributes_metadata[0]); i++) {
        if (!register_attribute_with_protocol(protocol_struct, &cam_example_attributes_metadata[i])) {
            mmt_log_error("init_cam_example_proto_struct: cannot register attribute %s", cam_example_attributes_metadata[i].alias);
            return 0;
        }
    }
    if (!register_protocol(protocol_struct, PROTO_CAM_EXAMPLE)) {
        mmt_log_error("init_cam_example_proto_struct: cannot register protocol %d", PROTO_CAM_EXAMPLE);
        return 0;
    }
    if (!register_classification_function_with_parent_protocol(376 /* PROTO_UDP */, cam_example_classify_after_udp, 5)) {
        mmt_log_error("init_cam_example_proto_struct: cannot attach to the parent protocol udp");
        return 0;
    }
    /* User code (src/cam_example_impl.c) attaches the protocol to its other parents. */
    if (!cam_example_hook_register_parents(protocol_struct)) {
        mmt_log_error("init_cam_example_proto_struct: cam_example_hook_register_parents() failed");
        return 0;
    }
    return 1;
}

#ifndef CORE
int init_proto(void)
{
    return init_cam_example_proto_struct();
}
#endif
